// ─── Helper Functions ────────────────────────────────────────────────

export function getAllCategories(): Category[] {
  return categories
}

export function getCategoryBySlug(slug: string): Category | undefined {
  return categories.find(c => c.slug === slug)
}

export function getProductsBySubcategory(subcategory: string): Product[] {
  return products.filter(p => p.subcategory === subcategory)
}

export function getProductsByCategory(category: string): Product[] {
  return products.filter(p => p.category === category)
}

export function getProductBySlug(slug: string): Product | undefined {
  return products.find(p => p.slug === slug)
}

export function getFeaturedProducts(limit = 8): Product[] {
  return products.filter(p => p.badge === 'Featured' || p.rating >= 4.8).slice(0, limit)
}

export function getNewArrivals(limit = 8): Product[] {
  return products.filter(p => p.badge === 'New').concat(products.filter(p => !p.badge)).slice(0, limit)
}

export function getRelatedProducts(product: Product, limit = 4): Product[] {
  return products
    .filter(p => p.subcategory === product.subcategory && p.id !== product.id)
    .slice(0, limit)
}

export function getSaleProducts(limit = 8): Product[] {
  return products
    .filter(p => p.badge === 'Sale' || (p.originalPrice != null && p.originalPrice > p.price))
    .slice(0, limit)
}
